//! Build script for `pathland-render-qt`: locate a Qt6 install via
//! `qmake -query`, run moc on the QML-facing bridge, compile the C++ widget
//! layer with `cc`, and hand the linker the Qt frameworks/dylibs.
//!
//! Qt location overrides: `QMAKE` env var (else Homebrew `/opt/homebrew/opt/qtbase/bin/qmake`,
//! else `qmake6`/`qmake` on PATH). Linux (CI) ships qmake at `/usr/bin/qmake6` and
//! moc at `/usr/lib/qt6/libexec/moc`.

use std::env;
use std::path::PathBuf;
use std::process::Command;

fn qmake_bin() -> PathBuf {
    if let Ok(q) = env::var("QMAKE") {
        return PathBuf::from(q);
    }
    for candidate in [
        "/opt/homebrew/opt/qtbase/bin/qmake",
        "/opt/homebrew/opt/qt/bin/qmake",
        "/usr/local/opt/qt/bin/qmake",
    ] {
        if PathBuf::from(candidate).exists() {
            return PathBuf::from(candidate);
        }
    }
    // Fall back to qmake6/qmake on PATH (Linux CI, other installs).
    for name in ["qmake6", "qmake"] {
        if Command::new(name).arg("-query").arg("QT_VERSION").output().is_ok() {
            return PathBuf::from(name);
        }
    }
    panic!(
        "Qt6 not found: set QMAKE=/path/to/qmake (Homebrew: brew install qtbase qtdeclarative, then QMAKE=$(brew --prefix qtbase)/bin/qmake)"
    );
}

fn qmake_query(qmake: &PathBuf, key: &str) -> String {
    let out = Command::new(qmake)
        .arg("-query")
        .arg(key)
        .output()
        .unwrap_or_else(|e| panic!("failed to run {qmake:?} -query {key}: {e}"));
    assert!(out.status.success(), "qmake -query {key} failed");
    String::from_utf8(out.stdout)
        .expect("qmake output not UTF-8")
        .trim()
        .to_string()
}

fn moc_name(header: &str) -> String {
    let base = header
        .rsplit('/')
        .next()
        .unwrap_or(header)
        .strip_suffix(".h")
        .unwrap_or(header);
    format!("moc_{base}")
}

fn find_moc(qmake: &PathBuf) -> PathBuf {
    let qt_bin = qmake.parent().expect("qmake must live in a bin dir");
    let prefix = qt_bin.parent().expect("qmake bin has a prefix");
    let candidates = [
        qt_bin.join("moc"),
        qt_bin.join("moc6"),
        prefix.join("share/qt/libexec/moc"),
        PathBuf::from("/opt/homebrew/share/qt/libexec/moc"),
        PathBuf::from("/usr/local/share/qt/libexec/moc"),
        PathBuf::from("/usr/lib/qt6/libexec/moc"),
        PathBuf::from("/usr/lib/x86_64-linux-gnu/qt6/libexec/moc"),
    ];
    for c in &candidates {
        if c.exists() {
            return c.clone();
        }
    }
    for name in ["moc", "moc6"] {
        if Command::new(name).arg("-V").output().is_ok() {
            return PathBuf::from(name);
        }
    }
    panic!(
        "moc not found (looked next to qmake and in standard Qt libexec paths); set QMAKE to a qtbase qmake"
    );
}

fn main() {
    let qmake = qmake_bin();
    let headers = qmake_query(&qmake, "QT_INSTALL_HEADERS");
    let libs = qmake_query(&qmake, "QT_INSTALL_LIBS");

    // Which Qt frameworks/dylibs do we need? QML controls call into a QObject
    // bridge via context-property invokables, so only Core/Qml/Quick + the
    // moc-generated meta-object code are required (no Controls C++ libs).
    let modules = ["QtCore", "QtGui", "QtQml", "QtQuick"];

    let framework_dir = |m: &str| PathBuf::from(&libs).join(format!("{m}.framework"));
    let frameworks = modules
        .iter()
        .filter(|m| framework_dir(m).exists())
        .cloned()
        .collect::<Vec<_>>();

    // Qt frameworks keep their public headers under a versioned subdir of
    // `<M>.framework/Headers/` (Homebrew layout); add those dirs so
    // `#include <QtQml/QQmlEngine>` resolves.
    let framework_header_dirs = |framework: &str| -> Vec<String> {
        let base = PathBuf::from(&libs).join(format!("{framework}.framework/Headers"));
        let mut dirs = Vec::new();
        if let Ok(rd) = std::fs::read_dir(&base) {
            for e in rd.flatten() {
                if e.file_type().map(|t| t.is_dir()).unwrap_or(false) {
                    dirs.push(e.path().to_string_lossy().into_owned());
                }
            }
        }
        dirs
    };

    let mut build = cc::Build::new();
    build
        .cpp(true)
        .files([
            "src/qt/qt_layer.cpp",
            "src/qt/bridge.cpp",
        ])
        .std("c++17");
    build.include(&headers);
    build.include("src/qt"); // so `#include "bridge.h"` / "pathland_qt.h" resolve
    for f in &frameworks {
        for d in framework_header_dirs(f) {
            build.include(&d);
        }
    }

    // moc the QML-facing bridge so QML can invoke its slot.
    let out_dir = env::var("OUT_DIR").expect("OUT_DIR set by cargo");
    let moc = find_moc(&qmake);
    for h in ["src/qt/bridge.h"] {
        let status = Command::new(&moc)
            .arg(h)
            .arg("-I")
            .arg("src/qt")
            .arg("-o")
            .arg(format!("{out_dir}/{}.cpp", moc_name(h)))
            .status()
            .unwrap_or_else(|e| panic!("failed to run moc on {h}: {e}"));
        assert!(status.success(), "moc on {h} failed");
        build.file(format!("{out_dir}/{}.cpp", moc_name(h)));
    }

    if !frameworks.is_empty() {
        build.flag(&format!("-F{libs}"));
        for f in &frameworks {
            println!("cargo:rustc-link-search=native={libs}");
            println!("cargo:rustc-link-lib=framework={f}");
        }
        // Frameworks are found via -F, not -L.
        println!("cargo:rustc-link-arg=-F{libs}");
    } else {
        // Plain shared lib layout (Linux): -L + -lQt6* + rpath.
        println!("cargo:rustc-link-search=native={libs}");
        for m in &modules {
            println!("cargo:rustc-link-lib=dylib={}", m.replace("Qt", "Qt6"));
        }
        println!("cargo:rustc-link-arg=-Wl,-rpath,{libs}");
    }

    build.compile("pathland_qt_layer");

    println!("cargo:rerun-if-env-changed=QMAKE");
    for f in [
        "src/qt/qt_layer.cpp",
        "src/qt/bridge.cpp",
        "src/qt/bridge.h",
        "src/qt/pathland_qt.h",
    ] {
        println!("cargo:rerun-if-changed={f}");
    }
}

// Shared C ABI types between the Rust decode core and the C++ Qt widget layer.
//
// A `PathlandQtCommand` is one delta: Rust produces a batch (mirroring the
// opcode engine's "only changes" discipline) and C++ applies it to the Qt Quick
// scene. This is deliberately a flat struct — the renderer's FFI boundary stays
// a batch of small commands, never a serialized tree.
#ifndef PATHLAND_QT_LAYER_H
#define PATHLAND_QT_LAYER_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum PathlandQtCommandKind {
    PLQT_CREATE_NODE = 0,   /* a=id, b=componentType(u16 low)                    */
    PLQT_DELETE_NODE = 1,   /* a=id                                              */
    PLQT_INSERT_CHILD = 2,  /* a=parent, b=child, c=index (u32::MAX = append)    */
    PLQT_REMOVE_CHILD = 3,  /* a=parent, b=child                                 */
    PLQT_MOVE_CHILD = 4,    /* a=parent, b=child, c=newIndex                     */
    PLQT_SET_TEXT = 5,      /* a=id, str=text                                    */
    PLQT_SET_PROPERTY = 6,  /* a=id, b=(valueType<<16)|propertyId, c=value       */
    PLQT_SET_STRING_PROPERTY = 7, /* a=id, b=propertyId, str=value              */
    PLQT_RESET_NODE = 8,    /* a=id — reset the widget to renderer defaults      */
    PLQT_SET_SCHEME = 9,    /* a=scheme (0 light, 1 dark)                        */
} PathlandQtCommandKind;

typedef struct PathlandQtCommand {
    uint8_t kind;
    uint32_t a;
    uint32_t b;
    uint32_t c;
    uint32_t str_len;
    const char *str;
} PathlandQtCommand;

/* Wake callback into the Rust host: a Qt event fired; the host drains its own
   event ring (renderer never drains). */
typedef void (*PathlandQtWake)(void *user);
/* Qt timer tick -> Rust pump (drain pending frames), like GTK's idle pump. */
typedef void (*PathlandQtTick)(void *user);

/* Own the Qt application shell (QGuiApplication + QQuickWindow + engine +
   root item + idle tick timer). Blocks until the window closes / quit. */
int pathland_qt_layer_run(const char *title, int width, int height,
                          PathlandQtWake wake, PathlandQtTick tick, void *user);

/* Apply a batch of delta commands to the Qt Quick scene. */
void pathland_qt_layer_apply(const PathlandQtCommand *cmds, uint32_t count);

/* Reset the whole scene (META::RESET). */
void pathland_qt_layer_reset(void);

/* Quit the event loop (host-initiated shutdown). */
void pathland_qt_layer_quit(void);

#ifdef __cplusplus
}
#endif

#endif /* PATHLAND_QT_LAYER_H */

// The QML-facing bridge: QML controls call its invokables (e.g. a Button's
// `onClicked: bridge.controlEvent(7)`), and it forwards to the Rust wake
// callback. This is the C++ widget layer's only surface back to the host —
// the host owns the transport + wire encoding and only needs to know "an
// event happened". See pathland_qt.h for the command/wake types.
#ifndef PATHLAND_QT_BRIDGE_H
#define PATHLAND_QT_BRIDGE_H

#include <QtCore/QObject>
#include "pathland_qt.h"

class Bridge : public QObject {
    Q_OBJECT
public:
    explicit Bridge(QObject *parent = nullptr);
    // Assigned by the shell; invoked when any QML control reports an input.
    PathlandQtWake wake = nullptr;
    void *user = nullptr;

public slots:
    // Called from QML: `onClicked: bridge.controlEvent(nodeId)` etc.
    void controlEvent(quint32 nodeId);
    // Programmatic value/state change echoes from a control (QML -> host).
    void valueEvent(quint32 nodeId);
    void textEvent(quint32 nodeId, const QString &text);
};

#endif // PATHLAND_QT_BRIDGE_H

#include "bridge.h"

Bridge::Bridge(QObject *parent) : QObject(parent) {}

void Bridge::controlEvent(quint32 nodeId) {
    Q_UNUSED(nodeId);
    if (wake) {
        wake(user);
    }
}

void Bridge::valueEvent(quint32 nodeId) {
    Q_UNUSED(nodeId);
    if (wake) {
        wake(user);
    }
}

void Bridge::textEvent(quint32 nodeId, const QString &text) {
    Q_UNUSED(nodeId);
    Q_UNUSED(text);
    if (wake) {
        wake(user);
    }
}

// The C++ Qt Quick shell for `pathland-render-qt`.
//
// Owns the Qt application objects (QGuiApplication / QQuickWindow / QQmlEngine /
// a root Item / the QML-facing Bridge) and the idle tick timer that pumps the
// ring on the Qt main thread. The shell is split so tests can `init` the scene
// headless (offscreen) and drive `apply` without entering the event loop.
//
// M2 skeleton: `apply` is a stub that records what it received (so Rust tests
// prove the FFI batch marshalling end-to-end); the real component->QML mapping
// lands in M3.

#include "pathland_qt.h"

#include <QtGui/QGuiApplication>
#include <QtQuick/QQuickWindow>
#include <QtQuick/QQuickItem>
#include <QtQml/QQmlEngine>
#include <QtQml/QQmlComponent>
#include <QtQml/QQmlContext>
#include <QtCore/QTimer>
#include <QtCore/QUrl>
#include <QtCore/QByteArray>
#include <QtCore/QString>
#include <QtCore/QDebug>

#include "bridge.h"

namespace {

struct LayerState {
    QGuiApplication *app = nullptr;
    QQmlEngine *engine = nullptr;
    QQuickWindow *window = nullptr;
    QQuickItem *root = nullptr; // window contentItem: parent of every top-level node
    Bridge *bridge = nullptr;
    QTimer *tick_timer = nullptr;
    bool initialized = false;

    // Test hooks: record what `apply` received (kept even after M3 mapping).
    uint32_t apply_count = 0;
    uint32_t last_text_len = 0;
    char last_text[4096] = {0};
};

LayerState g;

bool init_app(int argc, char **argv) {
    g.app = new QGuiApplication(argc, argv);
    return g.app != nullptr;
}

QQuickItem *createComponent(QQmlEngine *engine, QQuickItem *parent, const char *qml) {
    QQmlComponent comp(engine);
    comp.setData(QByteArray(qml), QUrl());
    if (comp.isError()) {
        qWarning() << "component error:" << comp.errorString();
        return nullptr;
    }
    QObject *obj = comp.create();
    if (!obj) {
        qWarning() << "create failed:" << comp.errorString();
        return nullptr;
    }
    QQuickItem *item = qobject_cast<QQuickItem *>(obj);
    if (item && parent) {
        item->setParentItem(parent);
    }
    return item;
}

} // namespace

extern "C" {

int pathland_qt_layer_init(PathlandQtWake wake, PathlandQtTick tick, void *user) {
    if (g.initialized) {
        return 0;
    }
    static int argc = 1;
    static char arg0[] = "pathland-qt";
    static char *argv[] = {arg0, nullptr};
    if (!init_app(argc, argv)) {
        return -1;
    }

    g.bridge = new Bridge(g.app);
    g.bridge->wake = wake;
    g.bridge->user = user;

    g.engine = new QQmlEngine(g.app);
    g.engine->rootContext()->setContextProperty("bridge", g.bridge);

    g.window = new QQuickWindow();
    g.window->setTitle(QString::fromUtf8("Pathland"));
    g.window->resize(420, 220);
    g.root = g.window->contentItem();

    // Idle tick: pump the ring on the Qt main thread between frames, like the
    // GTK renderer's glib idle pump. A zero-millisecond repeating timer runs
    // when the event loop is free.
    g.tick_timer = new QTimer(g.app);
    g.tick_timer->setInterval(0);
    g.tick_timer->setSingleShot(false);
    QObject::connect(g.tick_timer, &QTimer::timeout, g.app, [tick, user]() {
        if (tick) {
            tick(user);
        }
    });

    g.initialized = true;
    return 0;
}

int pathland_qt_layer_run(const char *title, int width, int height,
                          PathlandQtWake wake, PathlandQtTick tick, void *user) {
    if (pathland_qt_layer_init(wake, tick, user) != 0) {
        return -1;
    }
    if (title) {
        g.window->setTitle(QString::fromUtf8(title));
    }
    if (width > 0 && height > 0) {
        g.window->resize(width, height);
    }
    g.tick_timer->start();
    g.window->show();
    const int rc = g.app->exec();
    return rc;
}

void pathland_qt_layer_apply(const PathlandQtCommand *cmds, uint32_t count) {
    if (!g.initialized || !cmds || count == 0) {
        return;
    }
    // M2: stub — record what crossed the boundary (mapping lands in M3).
    for (uint32_t i = 0; i < count; ++i) {
        const PathlandQtCommand &c = cmds[i];
        if (c.kind == PLQT_SET_TEXT && c.str && c.str_len > 0) {
            const uint32_t n = c.str_len < sizeof(g.last_text) - 1 ? c.str_len
                                                                   : sizeof(g.last_text) - 1;
            memcpy(g.last_text, c.str, n);
            g.last_text[n] = '\0';
            g.last_text_len = n;
        }
        // Other kinds are ignored until the real mapping lands (M3).
    }
    g.apply_count += count;
}

void pathland_qt_layer_reset(void) {
    g.apply_count = 0;
    g.last_text_len = 0;
    g.last_text[0] = '\0';
}

void pathland_qt_layer_quit(void) {
    if (g.app) {
        g.app->quit();
    }
}

// Test hooks ---------------------------------------------------------------

uint32_t pathland_qt_layer_apply_count(void) {
    return g.apply_count;
}

uint32_t pathland_qt_layer_last_text(char *out, uint32_t cap) {
    if (!out || cap == 0) {
        return g.last_text_len;
    }
    const uint32_t n = g.last_text_len < cap ? g.last_text_len : cap - 1;
    memcpy(out, g.last_text, n);
    out[n] = '\0';
    return n;
}

void pathland_qt_layer_shutdown(void) {
    delete g.window;
    g.window = nullptr;
    delete g.engine;
    g.engine = nullptr;
    delete g.app;
    g.app = nullptr;
    g.bridge = nullptr;
    g.tick_timer = nullptr;
    g.root = nullptr;
    g.initialized = false;
}

} // extern "C"

//! The Rust ↔ C++ FFI boundary: command batch (Rust → C++), the Qt shell
//! entry points, and the test hooks. Mirrors `src/qt/pathland_qt.h`.
//!
//! A [`Command`] is one delta — Rust produces a batch (the engine's "only
//! changes" discipline) and the C++ layer applies it to the Qt Quick scene.

use std::ffi::{c_char, c_void};
use std::os::raw::c_int;

/// One delta command handed to the C++ Qt layer. `str_` points into the
/// renderer's `RenderTree` strings and is only valid for the duration of the
/// enclosing [`crate::renderer::QtRenderer::apply_frame`] call.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct Command {
    pub kind: u8,
    pub a: u32,
    pub b: u32,
    pub c: u32,
    pub str_len: u32,
    pub str_: *const c_char,
}

impl Command {
    pub const CREATE_NODE: u8 = 0;
    pub const DELETE_NODE: u8 = 1;
    pub const INSERT_CHILD: u8 = 2;
    pub const REMOVE_CHILD: u8 = 3;
    pub const MOVE_CHILD: u8 = 4;
    pub const SET_TEXT: u8 = 5;
    pub const SET_PROPERTY: u8 = 6;
    pub const SET_STRING_PROPERTY: u8 = 7;
    pub const RESET_NODE: u8 = 8;
    pub const SET_SCHEME: u8 = 9;

    fn new(kind: u8, a: u32, b: u32, c: u32) -> Self {
        Self {
            kind,
            a,
            b,
            c,
            str_len: 0,
            str_: std::ptr::null(),
        }
    }

    fn with_str(kind: u8, a: u32, s: &str) -> Self {
        Self {
            kind,
            a,
            b: 0,
            c: 0,
            str_len: s.len() as u32,
            str_: s.as_ptr() as *const c_char,
        }
    }

    pub fn create_node(id: u32, component: u16) -> Self {
        Self::new(Self::CREATE_NODE, id, component as u32, 0)
    }
    pub fn delete_node(id: u32) -> Self {
        Self::new(Self::DELETE_NODE, id, 0, 0)
    }
    pub fn insert_child(parent: u32, child: u32, index: u32) -> Self {
        Self::new(Self::INSERT_CHILD, parent, child, index)
    }
    pub fn remove_child(parent: u32, child: u32) -> Self {
        Self::new(Self::REMOVE_CHILD, parent, child, 0)
    }
    pub fn move_child(parent: u32, child: u32, new_index: u32) -> Self {
        Self::new(Self::MOVE_CHILD, parent, child, new_index)
    }
    pub fn set_text(id: u32, text: &str) -> Self {
        Self::with_str(Self::SET_TEXT, id, text)
    }
    /// `b = (valueType << 16) | propertyId`, `c = raw value` — the same
    /// encoding the opcode wire uses.
    pub fn set_property(id: u32, prop: u16, value_type: u8, value: u32) -> Self {
        Self::new(Self::SET_PROPERTY, id, ((value_type as u32) << 16) | prop as u32, value)
    }
    pub fn set_string_property(id: u32, prop: u16, value: &str) -> Self {
        Self {
            kind: Self::SET_STRING_PROPERTY,
            a: id,
            b: prop as u32,
            c: 0,
            str_len: value.len() as u32,
            str_: value.as_ptr() as *const c_char,
        }
    }
    pub fn reset_node(id: u32) -> Self {
        Self::new(Self::RESET_NODE, id, 0, 0)
    }
    pub fn set_scheme(scheme: u8) -> Self {
        Self::new(Self::SET_SCHEME, scheme as u32, 0, 0)
    }
}

pub type Wake = extern "C" fn(*mut c_void);
pub type Tick = extern "C" fn(*mut c_void);

extern "C" {
    /// Own the Qt application shell; blocks until the window closes.
    pub fn pathland_qt_layer_run(
        title: *const c_char,
        width: c_int,
        height: c_int,
        wake: Wake,
        tick: Tick,
        user: *mut c_void,
    ) -> c_int;
    /// Apply a batch of delta commands to the Qt Quick scene.
    pub fn pathland_qt_layer_apply(cmds: *const Command, count: u32);
    /// Reset the whole scene (META::RESET).
    pub fn pathland_qt_layer_reset();
    /// Quit the event loop (host-initiated shutdown).
    pub fn pathland_qt_layer_quit();

    // Test hooks (init without an event loop; record what `apply` received).
    pub fn pathland_qt_layer_init(wake: Wake, tick: Tick, user: *mut c_void) -> c_int;
    pub fn pathland_qt_layer_apply_count() -> u32;
    pub fn pathland_qt_layer_last_text(out: *mut c_char, cap: u32) -> u32;
    pub fn pathland_qt_layer_shutdown();
}

/// Forward a command batch to the C++ layer.
pub fn apply(cmds: &[Command]) {
    if cmds.is_empty() {
        return;
    }
    // SAFETY: `cmds` strings point into the renderer's `RenderTree`, which is
    // not mutated during the call (same `apply_frame` borrow).
    unsafe { pathland_qt_layer_apply(cmds.as_ptr(), cmds.len() as u32) };
}

//! The Qt renderer: shared decode core (`RenderTree`) + a sent-state cache
//! that produces the delta command batch handed to the C++ Qt layer.
//!
//! The engine emits diffs, and this renderer forwards diffs: it keeps a mirror
//! of what the C++ layer already has (`sent`) and, per frame, emits only the
//! commands that change it — an unchanged tree emits **zero** commands. The C++
//! layer stays dumb (applies the batch, resets to renderer defaults on
//! `RESET_NODE`).

use std::collections::{HashMap, HashSet};

use pathland_core::{value_type, Frame};
use pathland_render_core::RenderTree;

use crate::ffi::Command;

/// Mirror of the C++ layer's state for one node.
#[derive(Debug, Default)]
struct SentNode {
    component: u16,
    text: Option<String>,
    props: HashMap<u16, u32>,
    strings: HashMap<u16, String>,
}

/// Pseudo-parent for tree roots: id `0` maps to the Qt window's contentItem.
pub const CONTENT_ITEM: u32 = 0;

/// The retained Qt renderer. Owns the decoded tree (shared core) and the
/// sent-state cache used to produce deltas.
pub struct QtRenderer {
    tree: RenderTree,
    sent: HashMap<u32, SentNode>,
    sent_children: HashMap<u32, Vec<u32>>,
}

impl Default for QtRenderer {
    fn default() -> Self {
        Self::new()
    }
}

impl QtRenderer {
    pub fn new() -> Self {
        Self {
            tree: RenderTree::default(),
            sent: HashMap::new(),
            sent_children: HashMap::new(),
        }
    }

    /// The decoded tree (shared renderer core).
    pub fn tree(&self) -> &RenderTree {
        &self.tree
    }

    /// Apply one opcode frame and forward the resulting delta batch to the
    /// C++ layer. Unchanged nodes produce no commands.
    pub fn apply_frame(&mut self, frame: &Frame<'_>) {
        self.tree.apply_frame(frame);
        let cmds = self.diff();
        crate::ffi::apply(&cmds);
    }

    /// Clear the whole scene (`META::RESET`): empty the tree and tell the C++
    /// layer to drop every widget.
    pub fn reset(&mut self) {
        self.tree = RenderTree::default();
        self.sent.clear();
        self.sent_children.clear();
        unsafe { crate::ffi::pathland_qt_layer_reset() };
    }

    /// Compute the delta batch vs the sent-state cache.
    ///
    /// Commands with strings point into `self.tree`'s owned strings; the
    /// returned batch is only valid while `self` is not mutated — callers must
    /// forward it immediately (as [`Self::apply_frame`] does).
    pub fn diff(&mut self) -> Vec<Command> {
        let mut cmds = Vec::new();

        // 1. Deletions first: nodes gone from the tree.
        let live: HashSet<u32> = self.tree.nodes.keys().copied().collect();
        let dead: Vec<u32> = self.sent.keys().copied().filter(|id| !live.contains(id)).collect();
        for id in dead {
            cmds.push(Command::delete_node(id));
            self.sent.remove(&id);
            self.sent_children.remove(&id);
        }

        // 2. Creates (pre-order, so a parent exists before its children are
        //    inserted, and a child before any insert references it).
        let order = self.pre_order();
        for &id in &order {
            if self.sent.contains_key(&id) {
                continue;
            }
            let node = self.tree.node(id).unwrap();
            cmds.push(Command::create_node(id, node.component_type));
            self.sent.insert(
                id,
                SentNode {
                    component: node.component_type,
                    ..SentNode::default()
                },
            );
        }

        // 3. Text + property deltas. On any property change we re-send the
        //    node's *complete* property set (preceded by RESET_NODE), so the
        //    C++ layer can reset removed properties to its renderer defaults.
        for &id in &order {
            let node = self.tree.node(id).unwrap();
            let s = self.sent.get_mut(&id).unwrap();

            if s.text != node.text {
                cmds.push(Command::set_text(id, node.text.as_deref().unwrap_or("")));
                s.text = node.text.clone();
            }
            if node.properties != s.props || node.strings != s.strings {
                cmds.push(Command::reset_node(id));
                for (prop, value) in &node.properties {
                    let vt = value_type_for(*prop);
                    cmds.push(Command::set_property(id, *prop, vt, *value));
                }
                for (prop, value) in &node.strings {
                    cmds.push(Command::set_string_property(id, *prop, value));
                }
                s.props = node.properties.clone();
                s.strings = node.strings.clone();
            }
        }

        // 4. Child order (parents before children already exist).
        for &id in &order {
            let node = self.tree.node(id).unwrap();
            let prev = self.sent_children.entry(id).or_default();
            cmds.extend(children_diff(id, prev, &node.children));
            *prev = node.children.clone();
        }

        // 5. Roots are children of the pseudo-parent 0 (window contentItem).
        let mut roots: Vec<u32> = order
            .iter()
            .copied()
            .filter(|&id| self.tree.node(id).map_or(false, |n| n.parent.is_none()))
            .collect();
        roots.sort_unstable();
        let prev_roots = self.sent_children.entry(CONTENT_ITEM).or_default();
        cmds.extend(children_diff(CONTENT_ITEM, prev_roots, &roots));
        *prev_roots = roots;

        cmds
    }

    fn pre_order(&self) -> Vec<u32> {
        let mut order = Vec::new();
        let mut roots: Vec<u32> = self
            .tree
            .nodes
            .keys()
            .copied()
            .filter(|&id| self.tree.node(id).map_or(false, |n| n.parent.is_none()))
            .collect();
        roots.sort_unstable();
        for r in roots {
            self.walk(r, &mut order);
        }
        order
    }

    fn walk(&self, id: u32, out: &mut Vec<u32>) {
        out.push(id);
        if let Some(node) = self.tree.node(id) {
            for c in node.children.clone() {
                self.walk(c, out);
            }
        }
    }
}

/// The opcode wire's value type for a property (same mapping the emit side
/// uses; the C++ layer needs it to interpret the raw u32).
fn value_type_for(prop: u16) -> u8 {
    match prop {
        // Numeric properties the Qt layer will interpret directly.
        _ if is_f32_property(prop) => value_type::F32,
        _ if is_u32_property(prop) => value_type::U32,
        _ => value_type::U32,
    }
}

fn is_f32_property(prop: u16) -> bool {
    matches!(
        prop,
        pathland_core::property_id::SPACING
            | pathland_core::property_id::WIDTH
            | pathland_core::property_id::HEIGHT
            | pathland_core::property_id::FONT_SIZE
            | pathland_core::property_id::OPACITY
            | pathland_core::property_id::BORDER_WIDTH
            | pathland_core::property_id::BORDER_RADIUS
            | pathland_core::property_id::PADDING
            | pathland_core::property_id::PADDING_TOP
            | pathland_core::property_id::PADDING_RIGHT
            | pathland_core::property_id::PADDING_BOTTOM
            | pathland_core::property_id::PADDING_LEFT
            | pathland_core::property_id::VALUE
            | pathland_core::property_id::MIN_VALUE
            | pathland_core::property_id::MAX_VALUE
            | pathland_core::property_id::STEP_VALUE
            | pathland_core::property_id::PROGRESS
    )
}

fn is_u32_property(prop: u16) -> bool {
    matches!(
        prop,
        pathland_core::property_id::ALIGNMENT
            | pathland_core::property_id::LINE_LIMIT
            | pathland_core::property_id::TEXT_ALIGNMENT
            | pathland_core::property_id::Z_INDEX
            | pathland_core::property_id::CONTENT_MARGINS
            | pathland_core::property_id::EVENT_LISTENERS
            | pathland_core::property_id::SELECTED
            | pathland_core::property_id::ENABLED
            | pathland_core::property_id::IS_SECURE
            | pathland_core::property_id::TOGGLE_STYLE
            | pathland_core::property_id::SHAPE_KIND
    )
}

/// Minimal child-order delta: for each index where the old and new children
/// differ, remove the stale child and insert the new one at that index.
fn children_diff(parent: u32, prev: &[u32], next: &[u32]) -> Vec<Command> {
    let mut cmds = Vec::new();
    let len = prev.len().max(next.len());
    for i in 0..len {
        let old = prev.get(i).copied();
        let new = next.get(i).copied();
        if old == new {
            continue;
        }
        if let Some(c) = old {
            cmds.push(Command::remove_child(parent, c));
        }
        if let Some(c) = new {
            cmds.push(Command::insert_child(parent, c, i as u32));
