        let host = pathland_core::Host::new(&mut mem, &layout);
        let frames = host.frames();
        // Frames borrow the memory; copy the first frame's bytes so tests can
        // keep it alive beyond the scope above.
        let f = &frames[0];
        let mut owned = pathland_core::Memory::default();
        owned.copy_from_frame(f);
        pathland_core::Frame::from_owned(owned)
    }

    #[test]
    fn first_frame_creates_tree_and_props() {
        let mut view = vstack![text("ab"), text("cd")].spacing(4.0).padding(8.0).build();
