            let mut buf2 = [0i8; 64];
            unsafe {
                pathland_qt_layer_widget_prop_text(1, c"spacing".as_ptr(), buf2.as_mut_ptr(), buf2.len() as u32)
            };
            assert_eq!(unsafe { CStr::from_ptr(buf2.as_ptr()) }.to_string_lossy(), "8");

